 * dueBy (yyyy-MM-dd) is fixed when it was created: the terms-th business day after its date for the terms of its person
 * (else their grade's, else the sheet's) in force on it, skipping Saturdays, Sundays and the sheet's holidays then on the list;
 * log is its status log, oldest first: each status it has had, the user who gave it, the sheet's today then and its due then;
 * deferredUntil (yyyy-MM-dd) is the date it was deferred until, null when it never was;
 * proofs is how many proofs it has been given (a claim whose due is above the proof threshold in force on its date — its
 * person's grade's own, else the sheet's — is
 * settled or approved only once it has one);
 * splitFrom is the number of the claim it was split off, null when it was not split off one;
 * lockedBy is the user whose open editor locks it for every other user, null when it is not locked;
 * lateEntry is whether it was added while the period containing its due-by was soft-closed;
 * reminded (yyyy-MM-dd) is the last day a reminder was written for it, null when it never was;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  dueBy: string;
  log: ClaimLogLine[];
  deferredUntil: string | null;
  proofs: number;
  splitFrom: string | null;
  lockedBy: string | null;
  lateEntry: boolean;
  reminded: string | null;
  ref: string | null;
  tags: string[];
  voidReason: string | null;
  comments: ClaimComment[];
  batch: number | null;
  lines: ClaimLine[];
  /** When it was added, on the sequence rates are saved on: a forward-only rate applies only to claims added after it. */
  added: number;
  waived: boolean;
};

/** A line of a claim: its label, its quantity (a whole number, at least 1) and its unit amount (two decimals). */
export type ClaimLine = { label: string; qty: number; unit: string };

/** A comment on a claim: the user who wrote it, the sheet's today then (yyyy-MM-dd) and its text. */
export type ClaimComment = { by: string; date: string; text: string };

/** A line of a claim's status log: the status, the user, the sheet's today (yyyy-MM-dd) and the due then (two decimals, or n/a). */
export type ClaimLogLine = { status: ClaimStatus; by: string; date: string; due: string };

/**
 * Whether a claim counts toward claimed, due-total and every live total: only OPEN, PENDING and SETTLED do,
 * and an open (or pending) one not when one of its person's `holds` covers its date and no statement binds it,
 * nor while it is deferred on the sheet's `today`.
// above the clerk limit makes the claim PENDING; a reject sends the reason typed beside it. A role
// allowed to reassign (standing rule: a steward) moves a DRAFT, OPEN or PENDING claim to the person chosen beside the
// Move button. A steward re-settles a SETTLED claim, freezing it again at today's figure. An OPEN claim is deferred to the
// date typed beside the Defer button. The Add proof button raises the claim's proofs count by one (not on a
// SETTLED or VOID claim, nor one due by a date in a closed period). The Split button splits the amount typed beside it off an
// OPEN claim into a new OPEN claim of the same person (more than 0.00 and less than the claim's amount). A steward
// re-dates an OPEN or PENDING claim to the date typed beside the Re-date button. While the sheet has void reasons, a void
// sends the reason chosen beside it (none chosen: the server refuses it). Delete sets a DRAFT claim aside as DELETED;
// Restore makes it a DRAFT again, only on the sheet's today it was deleted. An open whose due is above the review threshold
// makes the claim REVIEW; a steward's Review then opens it.
export function ClaimStatus({ claim }: { claim: Claim }) {
    },
    onError: () =>
      setError(`This ${claim.status} claim cannot be deferred to that date (only an OPEN claim, to a date after today, outside a closed period).`),
  });

  const split = useMutation({
    mutationFn: (amount: string) =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/split?user=${encodeURIComponent(user)}`, {
        amount,
      }),
    onSuccess: async () => {
      setSplitAmount('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(
        `This ${claim.status} claim cannot be split by that amount (only an OPEN claim, not deferred nor in a closed period, by more than 0.00 and less than its amount, by a role allowed to open a claim).`,
      ),
  });

  const redate = useMutation({
    mutationFn: (date: string) =>
      putJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/date?user=${encodeURIComponent(user)}`, {
        date,
      }),
    onSuccess: async () => {
      setRedateTo('');
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(
        `This ${claim.status} claim cannot be re-dated to that date (only a steward re-dates an OPEN or PENDING claim, not after its person's retirement, nor one due by a date in a closed period).`,
      ),
  });

  const proof = useMutation({
    mutationFn: () =>
      postJson<Claim>(`/api/sheets/${encodeURIComponent(sheet)}/claims/${claim.id}/proofs?user=${encodeURIComponent(user)}`, {}),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: claimsKey(sheet) });
    },
    onError: () =>
      setError(`This ${claim.status} claim cannot be given a proof (not a SETTLED or VOID claim, nor one in a closed period).`),
  });

  return (
    <>
      <span data-testid="claim-status">{claim.status}</span>{' '}
      {ACTIONS.map(({ action, label }) => (
        <button
          key={action}
          if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
            setError('Type the claim\'s new date as yyyy-mm-dd.');
            return;
          }
          once(() => redate.mutateAsync(date));
        }}
      >
        Re-date
      </button>
      Proofs: <span data-testid="claim-proofs">{claim.proofs}</span>{' '}
      <button
        type="button"
        data-testid="claim-proof"
        disabled={proof.isPending}
        onClick={() => {
          setError('');
          once(() => proof.mutateAsync());
        }}
      >
        Add proof
      </button>
      {error && <span data-testid="claim-error">{error}</span>}
    </>
  );
}

